			var arr = [];
			var gr = new GlideRecord('x_maim2_license_co_run_time_role');
			gr.query();
			while(gr.next()){
				arr.push(gr.role.name.toString());

			}
			return arr;

		}
		function getSFARoles(){
			var arr = [];
