// Client Script: Validate Phone Number
// Table: sys_user
// Type: onChange
// Field: phone

function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') return;

    var phoneRegex = /^\(\d{3}\) \d{3}-\d{4}$/; // Format: (123) 456-7890
    if (!phoneRegex.test(newValue)) {
        g_form.showFieldMsg('phone', 'Phone number must be in the format (123) 456-7890', 'error');
        g_form.setValue('phone', '');
    }
}

function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) return;

    var fieldName = control.name;

    // Split the string
    var area = newValue.substring(1, 4);
    var firstThree = newValue.substring(6, 9);
    var lastFour = newValue.substring(10, 14);

    if (
        newValue[0] !== '(' || newValue[4] !== ')' || newValue[5] !== ' ' || newValue[9] !== '-' ||
        isNaN(parseInt(area)) || isNaN(parseInt(firstThree)) || isNaN(parseInt(lastFour))
    ) {
        g_form.showFieldMsg(
                fieldName,
                'Phone Number must be in the format (123) 456-7890',
                'error',
                false
            );
        g_form.setValue(fieldName, '');
    }
}

