// INPUT ARGUMENTS
// content - Base 64 of an attachment
// fileName - Name of the attachment that should be created with extension eg incidents.xls
// contentType - Content Type value of the attachment eg 	application/vnd.ms-excel, image/jpeg
// table - Table where the new attachment should be uploaded
// record - Record where the new attachment should be uploaded

// OUTPUT ARGUMENTS
// attachmentId - sys_id of attachment
/*************************************************************************************/

function convertBase64ToAttachment(content, fileName, contentType, table, record) {
    var attachRecord = new GlideRecord(table);
    if(attachRecord.get(record)){
		  var sysAttachment = new GlideSysAttachment();
		  var decodeAttachment = GlideStringUtil.base64DecodeAsBytes(content);
		  var attachmentId = sysAttachment.write(attachRecord, fileName, contentType, decodeAttachment);
		  return attachmentId;
	}else{
		return "Record not found";
	}	
}

/********************************************************************************/
Input:
attachmentQuery - Pass an encoded query to access the CSV attachment

Output:
Logs each rows and columns in the CSV file, use according to your logic

/********************************************************************************/

function parseCSVFile(attachmentQuery) {
    var attachmentRecord = new GlideRecord("sys_attachment");
    attachmentRecord.addEncodedQuery(attachmentQuery);
    attachmentRecord.query();
    if (attachmentRecord.next()) {
        var stringUtil = new GlideStringUtil();
        var sysAttachment = new GlideSysAttachment();
        //Get the attachment content in bytes
        var bytesData = sysAttachment.getBytes(attachmentRecord);
        // Encoded and decode the attachment content into a string
        var encData = stringUtil.base64Encode(bytesData);
        var decData = stringUtil.base64Decode(encData) + '';

        //Specify seperator and quote character to parse correctly
        var delimiter = ',';
        var quoteCharacter = '"';
        //Split into different rows
        var csvArray = decData.split("\r\n");
        for (var row in csvArray) {
            if (!!csvArray[row]) {
                //Parse each row through the parser and extract each columns
                var csvParser = new sn_impex.CSVParser().parseLineToArray(csvArray[row], delimiter, quoteCharacter);
                //Depending on number of columns, specify array index to access or loop them
                gs.info(row + " - " + csvParser[0] + " - " + csvParser[1]);
            }
        }
    }
}

function calculateHash(attachmentId){
    var attachmentStream = new GlideSysAttachment().getContentStream(attachmentId);
    var gDigest = new GlideDigest();
    var sha256Hash = gDigest.getSHA256HexFromInputStream(attachmentStream);
    if (sha256Hash) {
        gs.info("Hash code of the attachment file: " + sha256Hash);
    }
}

