function isValidJSON(str) {
    try {
        // Try to parse the string as JSON
        JSON.parse(str);
    } catch (e) {
        // If an error occurs, the string is not valid JSON
        return false;
    }
    // If no error occurs, the string is valid JSON
    return true;                    
}

