(function executeRule(current, previous /*null when async*/) {
    // Run only when change_request moves to Closed
    if (current.state != previous.state && current.state == 3) { // 3 = Closed
        var incidentSysId = current.incident;  // assuming there is a reference field to Incident

        if (!incidentSysId) {
            gs.info("No related incident found for this change request: " + current.number);
            return;
        }

        // Query for other open change requests linked to the same incident
        var otherCR = new GlideRecord('change_request');
        otherCR.addQuery('incident', incidentSysId);
        otherCR.addQuery('sys_id', '!=', current.sys_id);
        otherCR.addQuery('state', '!=', 3); // not closed
        otherCR.query();

        if (otherCR.hasNext()) {
            gs.info("Incident " + incidentSysId + " still has open change requests. Not closing incident.");
            return;
        }

        // If no open change requests remain, close the incident
        var inc = new GlideRecord('incident');
        if (inc.get(incidentSysId)) {
            inc.state = 7; // 7 = Closed (modify as per your instance)
            inc.close_code = 'Auto Closed';
            inc.close_notes = 'Incident auto-closed as all associated change requests are closed.';
            inc.update();
            gs.info("Incident " + inc.number + " auto-closed as all related change requests are closed.");
        }

    }
})(current, previous);

(function executeRule(current, previous /*null when async*/) {

    // ==============================================================
    // Business Rule: Incident Auto-Tagging
    // Table: Incident
    // --------------------------------------------------------------
    // Purpose:
    // Automatically detect keywords (like "email", "vpn", "server")
    // from the Incident’s short description and description fields.
    //
    // Based on detected keywords:
    //  - A corresponding Label is created (if not already present)
    //  - A related Label Entry is created for that Incident
    //
    // 💡 Benefit:
    // Adding Labels and Label Entries helps automatically tag
    // incidents with the right keywords — improving searchability,
    // categorization, and visibility across the platform.
    // ==============================================================

    // Step 1: Collect tags from the description
    var tags = [];
    var desc = (current.short_description + " " + current.description).toLowerCase();

    if (desc.indexOf("email") > -1) tags.push("Email");
    if (desc.indexOf("vpn") > -1) tags.push("VPN");
    if (desc.indexOf("server") > -1) tags.push("Server");

    // Step 2: Process each detected tag
    for (var i = 0; i < tags.length; i++) {

        var tagName = tags[i]; // e.g., "Email"
        var labelSysId;

        // Step 2.1: Check if Label already exists
        var labelGR = new GlideRecord("label");
        labelGR.addQuery("name", tagName);
        labelGR.query();

        if (labelGR.next()) {
            // Label exists — reuse it
            labelSysId = labelGR.sys_id.toString();
        } else {
            // Create new Label
            var newLabel = new GlideRecord("label");
            newLabel.initialize();
            newLabel.name = tagName;
            newLabel.owner = gs.getUserID();       // Logged-in user sys_id
            newLabel.viewable_by = "everyone";     // Backend value of choice
            newLabel.active = true;
            labelSysId = newLabel.insert();
        }

        // Step 2.2: Create Label Entry if not already present
        var entryGR = new GlideRecord("label_entry");
        entryGR.addQuery("table_key", current.sys_id);
        entryGR.addQuery("label", labelSysId);
        entryGR.query();

        if (!entryGR.hasNext()) {

            var newEntry = new GlideRecord("label_entry");
            newEntry.initialize();
            newEntry.title = "Incident - " + current.number; // e.g., Incident - INC0010003
            newEntry.label = labelSysId;
            newEntry.url = "incident.do?sys_id=" + current.sys_id + "&sysparm_view=";
            newEntry.table = "incident";
            newEntry.id_type = "Incident";
            newEntry.table_key = current.sys_id;
            newEntry.read = "yes"; 
            newEntry.insert();
        }
    }

})(current, previous);

// Business Rule: After Insert or After Update on change_request
// Purpose: Create Change Tasks for each affected CI and notify its owner
(function executeRule(current, previous /*null when insert*/) {

    // Query the task_ci table to get all CIs linked to this Change Request
    var ciRel = new GlideRecord('task_ci');
    ciRel.addQuery('task', current.sys_id);
    ciRel.query();

    while (ciRel.next()) {
        var ci = ciRel.ci_item.getRefRecord();  // Fetch the actual CI record

        if (ci.owner) {  // Proceed only if CI has an owner

            // Check if a Change Task for this CI and owner already exists
            var existingTask = new GlideRecord('change_task');
            existingTask.addQuery('change_request', current.sys_id);
            existingTask.addQuery('cmdb_ci', ci.sys_id);
            existingTask.addQuery('assigned_to', ci.owner);
            existingTask.query();

            if (!existingTask.next()) {
                // Create new Change Task for CI Owner
                var ct = new GlideRecord('change_task');
                ct.initialize();
                ct.change_request = current.sys_id;
                ct.cmdb_ci = ci.sys_id;
                ct.assigned_to = ci.owner;
                ct.short_description = 'Review Change for your CI: ' + ci.name;
                ct.insert();

                // Trigger a notification event
                gs.eventQueue('change.ci.owner.notification', ct, ci.owner, current.sys_id);
            }
        }
    }

})(current, previous);

