/* Secnario :
Whenever a record (for example, an Incident) is created or updated,
ServiceNow will automatically send a text prompt (like short description or work notes)
to OpenAI ChatGPT API, get the response, and save it back to a field (like u_ai_summary)*/

-----
//Business Rule Script (After Insert)
    try {
        // Build the prompt dynamically from the record
        var userPrompt = "Summarize this issue in one sentence: " + current.short_description;
        if (!userPrompt) return;

        // Prepare REST Message
        var rest = new sn_ws.RESTMessageV2('OpenAI ChatGPT', 'POST'); // name & method
        rest.setStringParameter('prompt', userPrompt); // replaces ${prompt} in body

        // Execute API call
        var response = rest.execute();
        var responseBody = response.getBody();
        var status = response.getStatusCode();

        if (status != 200) {
            gs.error("OpenAI API error: " + responseBody);
            return;
        }

        // Parse and store response
        var data = new global.JSON().decode(responseBody);
        var aiResponse = data.choices[0].message.content;

        // Save to custom field (u_ai_summary)
        current.u_ai_summary = aiResponse;
        current.update();

        gs.info("AI Summary added for incident: " + current.number);

    } catch (e) {
        gs.error("Error calling OpenAI ChatGPT: " + e.message);
    }

(function executeRule(current, previous /*null when async*/ ) {


    var notdt = new GlideDateTime();

// Setting next notification date (NND) to 14 days from record create date or any other state that your record begins with
	//change state value per your needs

        if (current.state == 602) {                                             
            notdt.addDaysLocalTime(14);
            current.next_notification_date = notdt.getLocalDate();
        } else if (current.state == 603 || current.state == 18) {               // In Progress, Awaiting Info  or any other state
            /* Setting the first "Next Notification Date" (NND) to 3 weekdays from current day
               If adding 3 days makes it a Sat we need to add two more days so that the NND is a Monday. 
	       If adding 3 days makes it a Sat then add two more days so that the NND is a Monday. 
	       If adding 3 days makes it a Sun then add 1 more day so that the NND is a Monday */
            notdt.addDaysLocalTime(3);
            if (notdt.getDayOfWeekLocalTime() == 6) {
                notdt.addDaysLocalTime(2);
                current.next_notification_date = notdt.getLocalDate();
            } else {
                if (notdt.getDayOfWeekLocalTime() == 7) {
                    notdt.addDaysLocalTime(1);
                    current.next_notification_date = notdt.getLocalDate();
                } else {
                    current.next_notification_date = notdt.getLocalDate();
                }
