(function() {
    var inactiveDays = 90;
    var cutoffDate = new GlideDateTime();
    cutoffDate.addDaysUTC(-inactiveDays);

    var userGR = new GlideRecord('sys_user');
    userGR.addActiveQuery(); // Only active users
    userGR.addQuery('sys_created_on', '<', cutoffDate); // Old accounts

    // Using encoded query: users with last login before cutoff OR never logged in
    userGR.addEncodedQuery('last_login_time<' + cutoffDate.getValue() + '^ORlast_login_timeISEMPTY');
    userGR.query();

    while (userGR.next()) {
        var wasActive = userGR.active;
        var managerSysId = userGR.manager;

        // Deactivate the user
        userGR.active = false;
        userGR.update();

        // Notify only if manager exists and is active
        if (wasActive && managerSysId) {
            var mgrGR = new GlideRecord('sys_user');
            mgrGR.addQuery('sys_id', managerSysId);
            mgrGR.addQuery('active', true);
            mgrGR.query();

            if (mgrGR.next()) {
                gs.eventQueue(
                    'user.deactivation.notify_manager',  // Event name
                    userGR,                              // Current user record
                    userGR.name.toString(),              // parm1: user's name
                    mgrGR.email.toString()               // parm2: manager's email
                );
            }
        }
    }

    gs.info('Inactive or never-logged users deactivated; active managers notified.');
})();

var groupGr = new GlideRecord('sys_user_group');
groupGr.addActiveQuery();
groupGr.query();
while (groupGr.next()) {
    var groupSysId = groupGr.sys_id.toString();
	// Query Group member table
    var memberGr = new GlideRecord('sys_user_grmember');
    memberGr.addQuery('group', groupSysId);
    memberGr.query();
    if (memberGr.hasNext()) {
		// If group has member but date is also populated that means member has joined recently. Clear the field value.
        if (!gs.nil(groupGr.u_memberless_date)) {
            groupGr.u_memberless_date = '';
            groupGr.update();
        }
    } else {
        var today = new GlideDate();
        if (gs.nil(groupGr.u_memberless_date)) {
			// If group doesn't have member populate the fields with today's date if doesn't have a value.
            groupGr.u_memberless_date = today;
            groupGr.update();
        } else {
			// If the field value is present compare the dates and deactivate group accordingly.
            var fieldDate = groupGr.getValue('u_memberless_date');
            today.addMonths(-6);
            if (fieldDate < today) {
                groupGr.active = false;
				groupGr.description = "Group has been deactivated for not having members in last 6 months.";
                groupGr.update();
            }
        }
    }
}

