// INPUT ARGUMENTS
// days - Create a system property "job.days.execute" and specify the number of days as comma separated values eg 1,3,5 
// 1 - Monday, 2 - Tuesday, 3 - Wednesday, 4 - Thursday, 5 - Friday, 6 - Saturday and 7 - Sunday

// hours - Create a system property "job.hours.execute" and specify the time as comma separated values eg 6,12,18,24
// 1-1am, 12-12pm, 18-6pm and 24-12am 

// OUTPUT ARGUMENTS
// execute - Returns true or false and determines whether the job should be executed or not
/*************************************************************************************/

executeJob();

function executeJob() {
    var execute = false;
    var days = gs.getProperty('job.days.execute');
    var hours = gs.getProperty('job.hours.execute');

    var dateTime = new GlideDateTime();
    var dayOfWeek = dateTime.getDayOfWeekLocalTime();
    var timeOfDay = dateTime.getLocalTime().toString().split(" ")[1];
    var hourOfDay = parseInt(timeOfDay.split(":")[0]);

    if (days.indexOf(dayOfWeek) > -1 && hours.indexOf(hourOfDay) > -1) {
        execute = true;
    }

    return execute;
}

var impGR = new GlideRecord(data_source.import_set_table_name);
impGR.addQuery('sys_import_set', import_set.sys_id);
impGR.query();

while (impGR.next()) {
    var classDisplayName = impGR.getValue('u_class');//column name as in staging table
    var supportGroupName = impGR.getValue('u_support_group');//column name as in staging table
    var managedByGroupName = impGR.getValue('u_managed_by_group');//column name as in staging table

    if (!classDisplayName) {
        gs.warn('[Import] Skipping row with empty class.');
        continue;
    }

    var classTable = '';
    var dbObjGR = new GlideRecord('sys_db_object');
    dbObjGR.addQuery('label', classDisplayName);
dbObjGR.addEncodedQuery('nameSTARTSWITHu_cmdb_ci^ORnameSTARTSWITHcmdb_ci');//custom CMDB table names are prepended with u_cmdb_ci
    dbObjGR.query();
    if (dbObjGR.next()) {

        classTable = dbObjGR.getValue('name');
    }

    if (!classTable) {
        gs.warn('[Import] Could not find table for class: ' + classDisplayName);
        continue;
    }

    var supportGroupId = '';
    var managedByGroupId = '';

    var groupGR = new GlideRecord('sys_user_group');
    groupGR.addQuery('name', 'IN', supportGroupName + ',' + managedByGroupName);
    groupGR.query();
    while (groupGR.next()) {
        var name = groupGR.getValue('name');
        if (name === supportGroupName) supportGroupId = groupGR.getUniqueValue();
        if (name === managedByGroupName) managedByGroupId = groupGR.getUniqueValue();
    }

    if (!supportGroupId || !managedByGroupId) {
        gs.warn('[Import] Missing group sys_id for: ' + supportGroupName + ' or ' + managedByGroupName);
        continue;
    }


    var ciGR = new GlideRecord(classTable);
    ciGR.addEncodedQuery('Optional-Filters');
    ciGR.query();
    if (!ciGR.hasNext()) {
        gs.warn('[Import] No CI found in ' + classTable + ' with name: ' + classDisplayName);
    }

    while (ciGR.next()) {
        ciGR.setValue('support_group', supportGroupId);
        ciGR.setValue('managed_by_group', managedByGroupId);
        ciGR.update();
    }
}

(function() {
    // Step 1: Define the date range for the previous month
    var startOfMonth = new GlideDateTime();
    startOfMonth.setValue(gs.beginningOfLastMonth());

    var endOfMonth = new GlideDateTime();
    endOfMonth.setValue(gs.endOfLastMonth());

    // Step 2: Query all incidents created in that month
    var gr = new GlideRecord('incident');
    gr.addQuery('opened_at', '>=', startOfMonth);
    gr.addQuery('opened_at', '<=', endOfMonth);
    gr.query();

    // Step 3: Build a map of category counts
    var categoryCount = {};
    while (gr.next()) {
        var category = gr.category ? gr.category.toString() : 'Uncategorized';
        categoryCount[category] = (categoryCount[category] || 0) + 1;
    }

    // Step 4: Build report body
    var reportBody = '';
    var total = 0;

    for (var categoryName in categoryCount) {
        total += categoryCount[categoryName];
        reportBody += categoryName + ': ' + categoryCount[categoryName] + '\n';
    }

    if (total === 0) {
        reportBody = 'No incidents were created in the last month.';
    } else {
        reportBody = 'Total Incidents: ' + total + '\n\n' + reportBody;
    }

    // Step 5: Add month name for better readability
    var monthName = gs.getMonthName(gs.monthsAgo(1));

    // Step 6: Trigger custom event to send email
    // parm1 = report body
    // parm2 = month name
    gs.eventQueue('custom.monthly.incident.report', null, reportBody, monthName);

    gs.info('Monthly Incident Report event triggered for ' + monthName);

})();

