                    value: incidentGr.getDisplayValue('assigned_to') || 'Unassigned',
                    short: true
                },
                {
                    title: 'Assignment Group',
                    value: incidentGr.getDisplayValue('assignment_group') || 'Unassigned',
                    short: true
                }
