var CustomUserUtils = Class.create();
CustomUserUtils.prototype = {
    initialize: function() {},

    /*
    	Parameters:
    		user : sys_id of user
    		role : role name

    	Returns: boolean
    		- true 	: if the user have the exact role
    		- false	: if the user does not have exact role
    */

    hasRoleExactly: function(user, role) {
        var roleGr = new GlideRecord('sys_user_has_role');
        roleGr.addQuery('user', user);
        roleGr.addQuery('role.name', role);
        roleGr.addQuery('state', 'active');
        roleGr.setLimit(1);
        roleGr.query();

        if (roleGr.next()) {
            return true;
        }
        return false;
    },

    /*
    	Parameters:
    		user : sys_id of user
    		role : list of comma seperated roles

    	Returns: Boolean
    		- true 	: if the user have any one of the exact role
    		- false	: if the user does not have any one of the exact role
    */
    hasAnyRoleExactly: function(user, roles) {
        var roleGr = new GlideRecord('sys_user_has_role');
        roleGr.addQuery('user', user);
        roleGr.addQuery('role.name', 'IN', roles);
        roleGr.addQuery('state', 'active');
        roleGr.setLimit(1);
        roleGr.query();

        if (roleGr.next()) {
            return true;
        }
        return false;
    },

    /*
    	Parameters:
    		user : sys_id of user
    		role : list of comma seperated roles

    	Returns: Boolean
    		- true 	: if the user have all of the roles exactly
    		- false	: if the user does not have any one of the role exactly
    */
    hasAllRoles: function(user, roles) {
        var roleGr = new GlideRecord('sys_user_has_role');
        roleGr.addQuery('user', user);
        roleGr.addQuery('role.name', 'IN', roles);
        roleGr.addQuery('state', 'active');
        roleGr.query();
        var actual_roles = [];
        while (roleGr.next()) {
            actual_roles.push(roleGr.role.name + '');
        }
		var arrayUtil = new ArrayUtil();
		actual_roles = arrayUtil.unique(actual_roles);
        var query_roles = roles.split(',');
        if (query_roles.length === actual_roles.length) {
            return true;
        }
        return false;
    },

    /*
    	Parameters:
    		user : sys_id of user
    		group : group name

    	Returns: Boolean
    		- true 	: if the user is member of the group
    		- false	: if the user is not member of the group
    */
    isMemberOf: function(user, group) {
        var grpGr = new GlideRecord('sys_user_grmember');
        grpGr.addQuery('user', user);
        grpGr.addQuery('group.name', group);
        grpGr.setLimit(1);
        grpGr.query();

        if (grpGr.next()) {
            return true;
        }
        return false;
    },

	/*
    	Parameters:
    		user : sys_id of user
    		groups : list of comma seperated group names

    	Returns: Boolean
    		- true 	: if the user is member of any of one of the groups
    		- false	: if the user is not member of any groups specified
    */
    isMemberOfAny: function(user, groups) {
        var grpGr = new GlideRecord('sys_user_grmember');
        grpGr.addQuery('user', user);
        grpGr.addQuery('group.name', 'IN', groups);
        grpGr.setLimit(1);
        grpGr.query();

        if (grpGr.next()) {
            return true;
        }
        return false;
    },

	/*
    	Parameters:
    		user : sys_id of user
    		groups : list of comma seperated group names

    	Returns: Boolean
    		- true 	: if the user is member of all the groups specified
    		- false	: if the user is not member of all the groups specified 
    */
    isMemberOfAll: function(user, groups) {
        var grpGr = new GlideRecord('sys_user_grmember');
        grpGr.addQuery('user', user);
        grpGr.addQuery('group.name', 'IN', groups);
        grpGr.query();
		var query_groups = groups.split(',');
		var actual_groups = [];
        while (grpGr.next()) {
            actual_groups.push(grpGr.group.name + '');
        }
		var arrayUtil = new ArrayUtil();
		actual_groups = arrayUtil.unique(actual_groups);

		if(query_groups.length === actual_groups.length){
			return true;
		}
        return false;
    },

    /*	
    	Returns: Array of user SysIDs
    */

    lineManagers: function() {
        var managers = [];
        var usrGa = new GlideAggregate("sys_user");
        usrGa.addQuery("active", "=", true);
        usrGa.addQuery("manager", "!=", "");
        usrGa.addAggregate("COUNT", "manager");
        usrGa.query();
        while (usrGa._next()) {
            managers.push(usrGa.getValue('manager'));
        }
        return managers;
    },

    type: 'CustomUserUtils'
};

var DataLookupUtils = Class.create();

DataLookupUtils.prototype = {
    initialize: function (tableName, sortByColumn) {
        this.tableName = tableName;
        this.columnNames = this._getColumnNames(tableName);
        this.queryColumns = this.columnNames;

        sortByColumn = sortByColumn || false;
        this.sortColumn = sortByColumn ? DataLookupUtils.SORT_BY_COLUMN : DataLookupUtils.SORT_BY_ORDER; // optional, use the field being retrieved or the built in order field
    },

    /**
     * query lookup data
     * can accept either an array of keys, or multiple parameters
     * e.g
     *    getLookupData('key1', 'key2', 'key3');
     *    getLookupData(['key1', 'key2', 'key3']);
     */
    getLookupData: function (_keys) {
        var keys = [];
        if (_keys && typeof _keys != 'object') {
            for (var _arg in arguments) {
                keys.push(arguments[_arg]);
            }
        } else {
            keys = _keys;
        }

        if (keys.length >= this.queryColumns.length) {
            NiceError.raise(gs.getMessage("Too many keys ({0}) provided.  Maximum is {1}", [keys.length.toString(), (this.queryColumns.length - 1).toString()]));
        }

        try {
            var fieldIdx = 0;
            var fieldName = this.queryColumns[fieldIdx];
            var gq = new global.GlideQuery(this.tableName)
                .where('active', true);

            if (keys.length > 0) {
                // loop through the keys
                keys.forEach(function (key, idx, arr) {
                    gq = gq.where(fieldName, key);
                    fieldName = this.queryColumns[++fieldIdx];
                }, this);
            }

            gq = gq.orderBy(this.sortColumn == DataLookupUtils.SORT_BY_COLUMN ? fieldName : 'order')
                .whereNotNull(fieldName)
                .select(fieldName)
                .map(function (_x) {
                    // just need the data, not the other stuff
                    return _x[fieldName];
                })
                .reduce(function (arr, e) {
                    // remove duplicates
                    if (arr.indexOf(e) == -1) arr.push(e);
                    return arr;
                }, []);

            return gq;
        } catch (e) {
            NiceError.raise(e);
        }
    },

    /**
     * override the columns to use for lookups
     * 
     */
    setColumns: function (columns) {
        if (columns.length == 0) return;

        this.queryColumns = [];
        columns.forEach(function (_col) {
            if (this.columnNames.indexOf(_col) > -1) {
                this.queryColumns.push(_col);
            } else {
                NiceError.raise(gs.getMessage('Cannot find column {0}.  Valid columns are {1}', [_col, this.columnNames.join(', ')]));
            }
        }, this);

    },

    /**
     * build the list of column names for the table
     * use the default system view for the table and exclude all system and inherited fields
     * column order determines key lookup
     */
    _getColumnNames: function () {
        return new global.GlideQuery('sys_ui_list_element')
            .where('list_id.name', this.tableName)
            .where('list_id.view', 'Default view')
            // ignore any system or inherited fields from the table
            .where('element', 'NOT IN', ['sys_class_name', 'sys_created_by', 'sys_created_on', 'sys_id', 'sys_mod_count', 'sys_name', 'sys_package', 'sys_policy', 'sys_scope', 'sys_updated_by', 'sys_updated_on', 'sys_update_name', 'active', 'order'])
            .whereNull('list_id.sys_user') // make sure we get the system view
            .orderBy('position')
            .select('element')
            .reduce(function (arr, e) {
                arr.push(e.element);
                return arr;
            }, []);
    },

    type: 'DataLookupUtils'
};

DataLookupUtils.SORT_BY_ORDER = 0;
DataLookupUtils.SORT_BY_COLUMN = 1;

