        //Begin to parse the excel sheet for relevant data
        var parser = new sn_impex.GlideExcelParser();
        parser.parse(attachmentStream);
        parser.setHeaderRowNumber(1);
        var headers = parser.getColumnHeaders(); // Array of headers
