        if (!field || !text || !delimiter) return "";

        var result = '';
        var regExp = new RegExp(field + delimiter + '(.*)', 'g');
        var match = text.match(regExp);
        if (match && match.length > 0) {
            var fieldList = match[0].split(delimiter);
            if (fieldList.length > 1) {
                result = fieldList[1].replace(/[\[\]]/g, '');
                result = result.trim();
            }
        }

        return result;
    },

    /**
     * 
     * @param {String} email to validate 
     * @returns returns true if valid email
     */
    isValidEmail: function(email) {
        if (!email) return false;
        var pattern = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
        return pattern.test(email.toLowerCase());
    },

    /**
     * 
     * @param {number} number to validate 
     * @returns returns true if the number is a positive integer
     */
    isInteger: function(number) {
        if (!number) return false;
        var regex = /^\d+$/;
        return regex.test(number);
    },

    /**
     * 
     * @param {number} number to validate 
     * @returns returns true if the number is a decimal digit
     * 
     * NB: This will match all the numbers in the form of 
     * 
     * 	3.14529, -255.34, 128, 1.9e10, 123,340.00
     */
    isDecimal: function(number) {
        if (!number) return false;
        var regex = /^-?\d+(,\d+)*(\.\d+(e\d+)?)?$/;
        return regex.test(number);
    },

    /**
     * 
     * @param {String} password to validate 
     * @returns returns true if the password contains One or More Upper, one or more Lower, and one or more Special character,
     * one or more numbers, and minimum of 8 characters
     * 
     * Example: Pa$$word1!
     */
    isStrongPassword: function(password) {
        if (!password) return false;
        // positive look ahead to check for each condition
        var regex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
        return regex.test(password);
    },

    /**
     * 
     * @param {Regex} regex : regex to execute. Regex should include groups
     * @param {string} text : text to execute the regex on 
     * @returns returns an array of all groups identified via regex
     * Example: var reg = new RegexUtils();
     * var groups = reg.executeGroups(/(\d{4})(\d{3})(\d{3})/gm, "0423394881");
	 *
	 * Or find all numbers in a string
	 * var reg = new RegexUtils();
	 * var result = reg.executeGroups(/\b\d+\b/g, 'A string with 3 numbers in it... 42 and 88.');
     */
    executeGroups: function(regex, text) {
        if (!regex || !text) return null;

        var groups = [];

        while ((m = regex.exec(text)) !== null) {
            // This is necessary to avoid infinite loops with zero-width matches
            if (m.index === regex.lastIndex) {
                regex.lastIndex++;
            }

            // The result can be accessed through the `m`-variable.
            m.forEach(function(match, groupIndex) {
                if (match) {
                    groups.push(match);
                }
            });
        }

        return groups;
    },

    type: 'RegexUtils'
};

var RequestApprovalHelper = Class.create();

RequestApprovalHelper.prototype = {
	initialize: function() {
	},

	///
	/// Checks all RTIMs approval status for a request
	/// Returns True if all RTIMs are approved or rejected
	///
	areAllRTIMsApprovedOrRejected : function(requestSysId) {
		var result = false;

		var rtimGR = new GlideRecord('sc_req_item');

		rtimGR.addQuery('request', requestSysId);
		rtimGR.query();

		// If ALL RTIMs are approved or rejected
		var allRTIMsHaveDecisionAndAtleastOneApproved = this._CheckForAllRTIMsApprovedOrRejected(rtimGR);

		if (allRTIMsHaveDecisionAndAtleastOneApproved) {
			result = true;
		}

		return result;
	},


	///
	/// Update the request and mark the flag that all RTIMs are approved or rejected
	///
	updateRequest : function(requestSysId){

		var rec = new GlideRecord('sc_request');
		rec.get(requestSysId);

		if(rec){
			rec.u_all_rtims_are_approved_or_rejected = true;
			rec.update();
		}

	},

	///
	/// Helper that checks all RTIMs have a decision i.e. Either approved or rejected e.g. not requested etc
	///
	_CheckForAllRTIMsApprovedOrRejected : function(rtimGR) {

		var result = false;
		var totalRecords = rtimGR.getRowCount();
		var approvedCounter = 0;
		var rejectedCounter = 0;

		while (rtimGR.next()) {

			var status = rtimGR.approval;

			if (status == 'approved') {
				approvedCounter += 1;
			}

			if (status == 'rejected') {
				rejectedCounter += 1;
			}
		}

		// At least one approved exist
		if (approvedCounter > 0) { 

			// All records either approved or rejected
			if(approvedCounter + rejectedCounter == totalRecords){
				result = true;
			}
		}

		return result;
	},

	type: 'RequestApprovalHelper'
};

var RequestNotificationUtil = Class.create();
RequestNotificationUtil.prototype = Object.extendsObject(RequestNotificationUtilSNC, {
    initialize: function() {
        RequestNotificationUtilSNC.prototype.initialize.apply(this, arguments);
    },

	/**
     * Get Reject comment from RITM - found that rejection notes added in EC will post
	 * to RITM record rather than Approval record
     * @param requestId - requestId
     * @returns comment based on the state for last rejected
     */
    getRejectCommentRITM: function(requestId) {
        var ritmRecord = new GlideRecord("sc_req_item");
        ritmRecord.addQuery('request', requestId);
        ritmRecord.orderBy('sys_updated_on');
        ritmRecord.setLimit(1);
        ritmRecord.query();
        while (ritmRecord.next()) {
            var commentDesc = ritmRecord.comments.getJournalEntry(1).toString();
            if (commentDesc.length > 0 && commentDesc.indexOf("Reason for rejection:") > -1) {
                var split = commentDesc.split(/\(Additional comments\)/gi);
                if (split.length > 1) {
                    // returns the first comment.
                    var comment = split[split.length - 1];
                    comment = comment.trim();
                    var colonIndex = comment.indexOf(':');
                    if (colonIndex != -1) {
                        comment = comment.substr(colonIndex + 2, comment.length - 1);
                    }
                    comment = comment.replace(/\n/g, '<br/>');
                    return comment;
                }
            }
        }
    },

    type: 'RequestNotificationUtil'
});

var RestMessageUtils = Class.create();
RestMessageUtils.prototype = {
    initialize: function(rmObj, restMessage, restFunc) {
        this.RM = (restFunc && restMessage) ? new sn_ws.RESTMessageV2(restMessage, restFunc) : new sn_ws.RESTMessageV2();
        this.rmObj = rmObj;
    },

    checkAndGetKeyValue: function(obj, key) {
        return obj.hasOwnProperty(key);

    },

    setQueryParams: function() {
        if (this.checkAndGetKeyValue(this.rmObj, 'queryParams'))
            for (var i in this.rmObj.queryParams)
                this.RM.setQueryParameter(i, this.rmObj.queryParams[i]);

    },

    variableSubs: function() {
        if (this.checkAndGetKeyValue(this.rmObj, 'variableInfo'))
            for (var i in this.rmObj.variableInfo)
                this.RM.setStringParameterNoEscape(i, this.rmObj.variableInfo[i]);
    },

    setAuth: function() {
        var authType = this.rmObj.authType;

        if (authType) {
            if (authType == 'APIKEY')
                return;
            else if (authType == 'BasicCreds')
                this.RM.setBasicAuth(this.rmObj.userName, this.rmObj.password);
            else if (authType == 'BasicAuthProfile')
                this.RM.setAuthenticationProfile('basic', this.rmObj.authProfile);

        }

    },

    setRequestBody: function() {
        if (this.checkAndGetKeyValue(this.rmObj, 'requestBody'))
            this.RM.setRequestBody(typeof this.rmObj.requestBody == 'object' ? JSON.stringify(this.rmObj.requestBody) : this.rmObj.requestBody);
    },

    setRequestHeaders: function() {
        if (this.checkAndGetKeyValue(this.rmObj, 'requestHeaders'))
            for (var i in this.rmObj.requestHeaders)
                this.RM.setRequestHeader(i, this.rmObj.requestHeaders[i]);
    },

    setMidServer: function() {
        if (this.checkAndGetKeyValue(this.rmObj, 'midServer'))
            this.RM.setMidServer(this.rmObj.midServer);
    },

    setEndpoint: function() {
        if (this.checkAndGetKeyValue(this.rmObj, 'endPoint'))
            this.RM.setEndpoint(this.rmObj.endPoint);
    },
    setHttpMethod: function() {
        if (this.checkAndGetKeyValue(this.rmObj, 'httpMethod'))
            this.RM.setHttpMethod(this.rmObj.httpMethod);
    },

    execute: function() {
        try {
            this.setHttpMethod();
            this.setEndpoint();
            this.setRequestHeaders();
            this.setAuth();
            this.setRequestBody();
            this.setQueryParams();
            this.variableSubs();
            this.setMidServer();
            return this.RM.execute();
        } catch (err) {
            gs.error('REST Message execution failed: ' + err);
        }

    },


    type: 'RestMessageUtils'
};

