/**
 * Script: Manager Email → Sys_id Map
 * Type: Transform Map Script (Run Script)
 *
 * Purpose:
 * This transform script builds an in-memory dictionary (map) that links
 * manager email addresses to their corresponding sys_ids in the `sys_user` table.
 *
 * Why:
 * During a data import or transform, multiple records may need to look up
 * the same manager repeatedly. Instead of running a GlideRecord query every time,
 * this preloads all manager sys_ids once for efficient lookup.
 *
 * Key Concept:
 * - `this.managerMap` is used instead of `var managerMap` so that the map
 *   persists across multiple transform runs (e.g., onBefore/transformRow/onAfter)
 *   within the same Transform Map execution context.
 * - Variables defined with `this` become properties of the transform script's
 *   execution object, allowing reuse across all functions available with the specific transform map pbject.
 *
 * Example usage in an onBefore/transformRow script:
 *   var managerSysId = this.managerMap[source.manager_email.toLowerCase()];
 */

(function runTransformScript(source, map, log, target /*undefined onStart*/) {
  // Build dictionary of Manager Emails → Sys_id
  this.managerMap = {};
  var grManagerUser = new GlideRecord("sys_user");
  grManagerUser.query();
  while (grManagerUser.next()) {
    managerMap[grManagerUser.email.toString().toLowerCase()] =
      grManagerUser.sys_id.toString();
  }
})(source, map, log, target);

(function runTransformScript(source, map, log, target /*undefined onStart*/) {
  // Name split
  if (source.u_full_name) {
    var parts = source.u_full_name.trim().split(/\s+/);
    target.first_name = parts[0];
    if (parts.length > 1) {
      target.last_name = parts.slice(1).join(" ");
    }
  }

  // Email normalize
  if (source.u_email) {
    target.email = source.u_email.toString().toLowerCase();
  }

  // Manager mapping
  var managerMap = this.managerMap;
  gs.info("manager map: " + managerMap);
  if (source.u_manager_email && managerMap) {
    var managerEmail = source.u_manager_email.toString().toLowerCase();
    var managerSysId = managerMap[managerEmail];
    gs.info("TM HR User Dump managerSysId: " + managerSysId);

    if (managerSysId) {
      target.manager = managerSysId;
    } else {
      log.warn(
        "Manager email not found: " +
          managerEmail +
          " for user " +
          source.u_full_name
      );
      target.manager = ""; // optional: blank manager instead of error
    }
  }
})(source, map, log, target);

// Transform Map onBefore script: set priority on insert, not on update
(function runTransformScript(source, map, log, target) {
  try {
    if (String(action).toLowerCase() !== 'insert') {
      log.info('Priority unchanged on update for number: ' + (target.number || '(new)'));
      return;
    }

    var impact = Number(source.impact) || 3;   // 1..3 typical
    var urgency = Number(source.urgency) || 3; // 1..3 typical

    // Simple matrix: priority = impact + urgency - 1, clamped 1..5
    var p = Math.max(1, Math.min(5, (impact + urgency) - 1));
    target.priority = String(p);
    log.info('Priority set on insert to ' + p);
  } catch (e) {
    log.error('Insert-only priority failed: ' + e.message);
  }
})(source, map, log, target);

function checkCSVHeaders(grAttachment, separator, acceptedColumns, reverseMatch) {

    var i = 0, l = 0;

    // Arrays of file columns and their corresponding lower case version
    var lcAcceptedColumns = [], attColumns = [], lcAttColumns = [];

    // Returned object
    var result = {
        error: false,
        unknownColumns: [],
        missingColumns: []
    };

    // Get the first line of the attachment (only support CSV for now)
    var firstLine = '';

    if (grAttachment.getValue('content_type') == 'text/csv') {

        // A pointer to the attachment in streaming mode
        var attachmentContentStream = (new GlideSysAttachment()).getContentStream(grAttachment.getValue('sys_id'));

        // Read the first line 
        firstLine =  new GlideTextReader(attachmentContentStream).readLine();

    } else {

        return undefined;
    }   

    // Remove all Byte Order Mark that may have been hidden in the CSV file
    firstLine = firstLine.replace(/\uFEFF/g, '');

    // Exit now if the first line has nothing
    if (JSUtil.nil(firstLine)) {

        return undefined;

    } else {

        // Make sure all accepted column names are in LC
        lcAcceptedColumns = acceptedColumns.map(function(value) {
            return value.toLowerCase();
        });

        // Get a lowercase version of all the columns of the attachement
        attColumns = firstLine.split(separator);
        lcAttColumns = attColumns.map(function(value) {
            return value.toLowerCase();
        });

        // Verify that all the columns of the template are accepted
        for (i = 0, l = lcAttColumns.length; i < l; i++) {
            if (lcAcceptedColumns.indexOf(lcAttColumns[i]) == -1) {
                result.unknownColumns.push('"' + attColumns[i] + '"');
            }
        }
        // Optionally, verify that we're not missing any columns in the template
        if (reverseMatch) {
            for (i = 0, l = lcAcceptedColumns.length; i < l; i++) {
                if (lcAttColumns.indexOf(lcAcceptedColumns[i]) == -1) {
                    result.missingColumns.push('"' + acceptedColumns[i] + '"');
                }
            }
        }
    }

    result.error = ((result.unknownColumns.length > 0) || (result.missingColumns.length > 0));
    return result;
}

