function analyzeDataFreshness(config) {
        var gr = new GlideRecord('cmdb_ci');
        gr.addQuery('sys_created_on', '>=', 'javascript:gs.daysAgoStart(' + config.thresholds.maxAge + ')');
        gr.setLimit(config.sampleSize);
