//This is such a wonderful question, and the frustration of how weird the API is in this particular case only heightened my delight at figuring it out.
//
//*The answer*:
//
//First: As you likely know, arrays in JavaScript are necessarily ordered, so element `0` will always be in the first position no matter what you do with it. 
//With that in mind, the API structure for list collectors is like this:

g_form.setValue(
    fieldName, //String
    fieldValues, //Comma-delimited string
    fieldDisplayValues //ARRAY!
);

//So you would be passing in two lists: one for the values, and one for the display values - but passing them in, in two different types!
//
//For example: Consider the following code:

var grIncident = new GlideRecord('incident');
grIncident.addQuery('some_field', 'some_val');
grIncident.query(function(grIncident) {
    var incidentIDs = [];
    var incidentNumbers = [];
    while (grIncident.next()) {
        incidentIDs.push(grIncident.getValue('sys_id'));
        incidentNumbers.push(grIncident.getValue('number'));
    }
    if ((incidentIDs.length > 0) && (incidentNumbers.length === incidentIDs.length)) {
        g_form.setValue('list_collector_field_name', incidentIDs.join(','), incidentNumbers);
    }
});

//Here, consider the 11th line: `g_form.setValue('list_collector_field_name', incidentIDs.join(','), incidentNumbers);`
//In this line, we're passing in three arguments: the field name, the value*s* we want, and their corresponding display values. 
//However, even though *both* `incidentIDs` and `incidentNumbers` are *array* variables, we only `.join(',')` *one* of them to a string (the *values* array). Otherwise, the API call will fail

function activeValue() {
  var appAray = [];
  var u_app_mod = new GlideRecord('u_app_mod');
  u_app_mod.addQuery('u_active', 'true');
  u_app_mod.query();
  while (u_app_mod.next()) {
    appAray.push(u_app_mod.getValue('u_application'));
  }
  return appAray.join(',');
}

(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
	// Declare Data Object
	var oData = request.body.data;
	// Declare the response object
	var oResponseObj = {};
	// Initialize Query to Incident table
	var oInc = new GlideRecord('incident');
	oInc.initialize();
	oInc.setValue('short_description', oData.short_description);
	oInc.description = oData.description;
	oInc.assignment_group.setDisplayValue(oData.assignment_group);
	oInc.setValue('caller_id', _getUser(oData.opened_by));
	oInc.setValue('opened_by', _getUser(oData.opened_by));
	oInc.setValue('category', "Service Request");
	oInc.setValue('contact_type', "email");
	oInc.setValue('location', gs.getUser().getUserByID(oData.opened_by).getLocation());
	// Insert the record
	oInc.insert();
	// Populate Response Object
	oResponseObj.number = oInc.number;
	oResponseObj.sys_id = oInc.sys_id;
	// Return response with number and sys_id to be stored on the remote end for reference
	return oResponseObj;
	/*
	* Helper Functions 
	*/
	// Returns sys_id from username passed in POST request
	function _getUser(userName) {
		var gr = new GlideRecord("sys_user");
		gr.addQuery("user_name", userName);
		gr.query();
		if(gr.next()) {
			return gr.sys_id;
		} else {
			// Return Generic WebSVC User SysId if not match is found
			return '99420aff6f7d92008212a4e44b3ee4ea';
		}
	}
})(request, response);

