        ga.getXML(displayFiltersAsynch, null, fDiv);
    } else if (fDiv.style.display == ''){
        fDiv.style.display = 'none';
        setImage(image, "images/filter_hide.gifx");
    } else {
        fDiv.style.display = '';
        setImage(image, "images/filter_reveal.gifx");
    }
}
