function trendFilter(item) {
    var name = item.getName();
    if (name.indexOf(".")  > -1 )
        return false;
    var type  = item.getType();
    if (dateTypes[type])
        return true;
    return false;
}
function sumFilter(item) {
    var name = item.getName();
    if (name.indexOf(".")  > -1 )
        return false;
    var type  = item.getType();
    if (numericTypes[type])
        return true;
    if (type == 'glide_duration' || type == 'timer')
        return true;
    return false;
}
function numericFilter(item) {
    var name = item.getName();
    if (name.indexOf(".")  > -1 )
        return false;
    var type  = item.getType();
    if (numericTypes[type])
        return true;
    return false;
}
function stackFilter(item) {
    var name = item.getName();
    if (name.indexOf(".")  > -1 )
        return false;
    var type  = item.getType();
    if (type == 'reference')
        return true;
    if (type == 'boolean')
        return true;
    var choice = item.getChoice();
    if (choice == 1 || choice == 3)
        return true;
    return false;
}
function dateFilter(item) {
    var name = item.getName();
    if (name.indexOf(".")  > -1 )
        return false;
    var type  = item.getType();
    if (dateTypes[type] || type == 'glide_duration')
        return true;
    var choice = item.getChoice();
    if (choice == 1 || choice == 3)
        return false;
    if (item.isNumber())
        return true;
    return false;
}
