function loadSubcategorySnippets(subcategory) {
            try {
                const path = `Core ServiceNow APIs/${subcategory}`;
                const contents = await fetchGitHubAPI(path);

                // Filter for directories (snippet folders)
                const snippetFolders = contents.filter(item => item.type === 'dir');

                // Get detailed info for each snippet
                const snippets = await Promise.all(
                    snippetFolders.map(async (folder) => {
                        try {
                            const snippetPath = `${path}/${folder.name}`;
                            const snippetContents = await fetchGitHubAPI(snippetPath);

                            // Find README and code files
                            const readmeFile = snippetContents.find(f => 
                                f.name.toLowerCase().includes('readme') && f.name.endsWith('.md')
                            );
                            const codeFiles = snippetContents.filter(f => 
                                f.name.endsWith('.js') || f.name.endsWith('.ts') || f.name.endsWith('.json')
                            );

                            return {
                                name: folder.name,
                                path: snippetPath,
